sys_variable_value.value:
(function execute(inputs, outputs) {
    let object_type;
    let request_type;

    switch (inputs.access_item_type.toString()) {
        case "role":
            object_type = "ROLE";
            break;
        case "accessprofile":
            object_type = "ACCESS_PROFILE";
            break;
        case "entitlement":
            object_type = "ENTITLEMENT";
            break;
    }

    switch (inputs.action.toString()) {
        case "Add":
            request_type = "GRANT_ACCESS";
            break;
        case "Remove":
            request_type = "REVOKE_ACCESS";
            break;
    }

    const request_body = {
        "requestedFor": [inputs.identity_id.toString()],
        "requestType": request_type,
        "requestedItems": [{
            "type": object_type,
            "id": inputs.access_item_id.toString(),
            "comment": `Submitted request via ${inputs.request_item.cat_item.name.toString()} (${inputs.request_item.number.toString()})`,
            "clientMetadata": {
                "sc_req_item_id": inputs.request_item.sys_id.toString(),
                "sc_req_item_number": inputs.request_item.number.toString(),
                "cat_item_id": inputs.request_item.cat_item.sys_id.toString(),
                "cat_item_name": inputs.request_item.cat_item.name.toString()
            }
        }],
        "clientMetadata": {
            "sc_req_item_id": inputs.request_item.sys_id.toString(),
            "sc_req_item_number": inputs.request_item.number.toString(),
            "cat_item_id": inputs.request_item.cat_item.sys_id.toString(),
            "cat_item_name": inputs.request_item.cat_item.name.toString()
        }
    };

    outputs.request_body = JSON.stringify(request_body);

    try {
        const request_response = new x_xal_idconnect.XalientUtilitiesCatalogItem().submitAccessRequest(request_body);

        if (request_response.getStatusCode() != 202) {
            throw `Issue creating access request in ISC - \r\n\r\n
		Request Body - \r\n\r\n${JSON.stringify(request_body)} \r\n
		Status Code ${request_response.getStatusCode()} \r\n
		Response Body - \r\n\r\n ${request_response.getBody()}`;


        } else {
            outputs.response_body = request_response.getBody();
            outputs.status_code = request_response.getStatusCode();
            
            const response_body = JSON.parse(request_response.getBody());
            const access_request_ids = [];
            for (const request of response_body.newRequests) {
                for (const item of request.accessRequestIds) {
                    access_request_ids.push(item);
                }
            }
            outputs.access_request_ids = access_request_ids.toString();
        }

    } catch (exception) {
        outputs.result = 'processing_exception';
        outputs.error_message = exception
    }
})(inputs, outputs);

